// Monta o resumo do cliente para o dashboard.
// Tempos médios: documentos = 300 ms, prazos = 500 ms, mensagens = 200 ms
public async Task<ResumoClienteDto> ObterResumo(string clienteId)
{
    var tarefaDocumentos = _documentoRepository.ListarPorCliente(clienteId);
    var tarefaPrazos = _prazoRepository.ListarPorCliente(clienteId);
    var tarefaMensagens = _mensagemRepository.ListarPorCliente(clienteId);

    await Task.WhenAll(tarefaDocumentos, tarefaPrazos, tarefaMensagens);

    var documentos = tarefaDocumentos.Result;
    var prazos = tarefaPrazos.Result;
    var mensagens = tarefaMensagens.Result;

    return new ResumoClienteDto
    {
        TotalDocumentos = documentos.Count,
        DocumentosPendentes = documentos.Count(d => d.Pendente),
        TotalPrazos = prazos.Count,
        MensagensNaoLidas = mensagens.Count(m => !m.Lida)
    };
}

