// Retorna o telefone do contato principal do cliente para o envio de aviso.
public async Task<Retorno> ObterTelefonePrincipal(string clienteId)
{
    var cliente = await _clienteRepository.GetById(clienteId);
    if (cliente == null)
        return Retorno.Erro("Cliente não encontrado");

    var contatoPrincipal = cliente.Contatos
        .Where(c => c.Ativo)
        .First(c => c.Principal);

    var telefone = contatoPrincipal.Telefone ?? "Sem telefone";

    return Retorno.Ok(telefone);
}

